    // visitor); only cut off something absurdly big.
    req.on("data", c => { size += c.length; if (size > limit * 20) req.destroy(); else if (size <= limit) chunks.push(c); });
    req.on("end", () => size > limit ? reject(new Error("too_large")) : resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
