  const email = store.normEmail(b.email);
  if (!store.validEmail(email)) return bad(res, 400, "bad_email", "That email doesn't look right. Check it and try again.");
  if (limited("signup", ip, 5, 3600e3)) return bad(res, 429, "rate_limited", "Too many sign-ups from here. Try again in an hour.");
  if (mail.enabled() && limited("signupmail", email, 3, 3600e3)) return bad(res, 429, "rate_limited", "We've sent a few emails to that address already. Check your inbox (and junk), or try again in an hour.");
  const wantsNews = Boolean(b.newsletter) && !mail.enabled();       // with email on, added only once they confirm (below)
  const existing = store.userByEmail(email);
  const checkEmail = () => send(res, 200, { status: "check_email", message: "Check your email: we've sent you a link to finish joining." });
  const mailFailed = e => { console.error("signup email:", e.message); return bad(res, 502, "email_failed", "We couldn't send the email just now. Try again in a few minutes."); };
  if (existing) {
    if (!mail.enabled()) return bad(res, 409, "exists", "That email already has an account. Sign-in emails aren't switched on for this site yet, so please contact us.");
    try { await mail.send({ to: email, subject: "Your Undercut sign-in link", html: mail.layout("Sign in to Undercut", "<p>Tap the button to sign in. The link works once, for 48 hours.</p>" + mail.button(loginLink(existing), "Sign in")) }); }
    catch (e) { return mailFailed(e); }
    return checkEmail();                       // same answer as a new sign-up, so nobody can test which emails have accounts
  }
  const inviter = b.ref ? store.userByRef(b.ref) : null;
  const u = {
    id: store.id(), email, createdAt: now(), refCode: crypto.randomBytes(4).toString("hex").slice(0, 6).toUpperCase(),
    referredBy: inviter && store.normEmail(inviter.email).replace(/\+[^@]*@/, "@") !== email.replace(/\+[^@]*@/, "@") ? inviter.id : null,
    verified: false, proUntil: 0, freeUnlockUsed: false, plan: null, tokenVersion: 1, wantsNews: Boolean(b.newsletter) || undefined
  };
  if (wantsNews) addSubscriber(email, "signup");
  store.db.users.push(u);
