    try { await mail.send({ to: email, subject: "Welcome to Undercut: confirm your email", html: mail.layout("You're nearly in", "<p>Tap the button to confirm your email and sign in. The link works once, for 48 hours.</p>" + mail.button(loginLink(u), "Confirm and sign in")) }); }
    catch (e) { store.db.users = store.db.users.filter(x => x !== u); return mailFailed(e); }
