"lib/postcode.js": function (module, exports, require, __dirname, __filename) {
// UK postcode check + lookup (postcodes.io, free, no key). The postcode is never stored on the server.
"use strict";
const BASE = () => process.env.POSTCODES_BASE || "https://api.postcodes.io";
const RE = /^([A-Z]{1,2}\d[A-Z\d]?)\s*(\d[A-Z]{2})$/;
const cache = new Map();
const DAY = 864e5;

// "cv12ab" -> "CV1 2AB"; null when it isn't shaped like a UK postcode
function normalise(input) {
  const t = String(input || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  const m = RE.exec(t.length > 4 ? t.slice(0, -3) + " " + t.slice(-3) : t);
  return m ? m[1] + " " + m[2] : null;
}

async function lookup(input) {
  const pc = normalise(input);
  if (!pc) return { ok: false, error: "bad_postcode", message: "That doesn't look like a UK postcode. Try something like CV1 2AB." };
  const hit = cache.get(pc);
  if (hit && Date.now() - hit.at < DAY) return hit.v;
  let v;
  try {
    const r = await fetch(BASE() + "/postcodes/" + encodeURIComponent(pc), { signal: AbortSignal.timeout(6000) });
    if (r.status === 404) return { ok: false, error: "unknown_postcode", message: "We couldn't find that postcode. Check it and try again." };
    const j = await r.json();
    const d = j && j.result;
    if (!r.ok || !d) throw new Error("lookup failed");
    const town = d.admin_district || d.parish || d.admin_ward || null;
    v = { ok: true, postcode: d.postcode || pc, town, region: d.region || d.country || "England", country: d.country || "England", lat: d.latitude, lng: d.longitude };
  } catch (e) {
    // lookup service unreachable: accept a correctly shaped postcode and localise by its area only
    v = { ok: true, postcode: pc, town: null, region: null, approximate: true };
    return v;   // not cached, so the next try can do the full lookup
  }
  cache.set(pc, { at: Date.now(), v });
  if (cache.size > 5000) cache.delete(cache.keys().next().value);
  return v;
}

// the place name Google Shopping is asked to localise to
function locationString(loc) {
  if (!loc || !loc.town) return "";
  return [loc.town, loc.country || "England", "United Kingdom"].join(", ");
}

module.exports = { normalise, lookup, locationString };

},
