// True when the listing doesn't contradict anything the shopper typed.
function specMatches(query, title) {
  const w = extract(query);
  if (w.cat === "general") return true;
  return conflicts(w, extract(title)).length === 0;
}

module.exports = { extract, conflicts, specMatches, brandOf };

