// Stripe over plain HTTPS (no SDK needed).
"use strict";
const crypto = require("node:crypto");

const KEY = () => process.env.STRIPE_SECRET_KEY || "";
const API = () => process.env.STRIPE_API_BASE || "https://api.stripe.com/v1";

function form(obj, prefix, out = []) {
  for (const [k, v] of Object.entries(obj)) {
    if (v === undefined || v === null) continue;
    const key = prefix ? `${prefix}[${k}]` : k;
    if (typeof v === "object") form(v, key, out);
    else out.push(encodeURIComponent(key) + "=" + encodeURIComponent(String(v)));
  }
  return out.join("&");
}

async function call(method, path, params) {
  const r = await fetch(API() + path, {
    method,
    headers: { Authorization: "Bearer " + KEY(), "Content-Type": "application/x-www-form-urlencoded" },
    body: params ? form(params) : undefined,
    signal: AbortSignal.timeout(20000)
  });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error((j.error && j.error.message) || ("Stripe returned " + r.status));
  return j;
}

// Verifies the Stripe-Signature header (t=...,v1=...) against the raw body.
function verifyWebhook(raw, header, secret, toleranceSec = 300) {
  if (!header || !secret) return false;
  const parts = Object.fromEntries(String(header).split(",").map(p => p.split("=")).filter(p => p.length === 2).map(([k, v]) => [k.trim(), v.trim()]));
  const sigs = String(header).split(",").filter(p => p.trim().startsWith("v1=")).map(p => p.trim().slice(3));
  const t = Number(parts.t);
  if (!t || !sigs.length || Math.abs(Date.now() / 1000 - t) > toleranceSec) return false;
  const expected = crypto.createHmac("sha256", secret).update(t + "." + raw).digest("hex");
  return sigs.some(s => s.length === expected.length && crypto.timingSafeEqual(Buffer.from(s), Buffer.from(expected)));
}

